package com.vlesscardvpn.core

import java.io.ByteArrayInputStream
import java.util.zip.GZIPInputStream
import java.security.MessageDigest
import okio.ByteString.Companion.decodeBase64
import org.json.JSONObject
import kotlin.math.tanh

/** Restricted real FlyWire-derived MB graph, not a complete fly or biological emulation.
 * Source: Betzel et al., Zenodo 18555170, CC BY 4.0. Details: docs/roki-connectome.md.
 * All-positive normalized synapse counts, tanh dynamics and engineered input/output adapters.
 * No network, files, changing VPN settings or persistent neural state. */
object FlyReservoir {
    const val NODES=516
    const val EDGES=11517
    const val GRAPH_SHA256="b3f94ee800f9555cb02f7c397c183af7e24e11ac5fb735e871849de997dd5b84"
    private val encoded=arrayOf("","","","","","","","").joinToString("")
    private data class Graph(val pre:IntArray,val post:IntArray,val weight:DoubleArray)
    private val graph:Graph by lazy {
        val zipped=requireNotNull(encoded.decodeBase64()).toByteArray()
        val raw=GZIPInputStream(ByteArrayInputStream(zipped)).use {it.readBytes()}
        require(raw.size<200000)
        require(MessageDigest.getInstance("SHA-256").digest(raw).joinToString("") {"%02x".format(it)}==GRAPH_SHA256)
        val json=JSONObject(raw.toString(Charsets.UTF_8))
        require(json.getJSONArray("nodes_zero_based_matlab_rows").length()==NODES)
        val edges=json.getJSONArray("edges");require(edges.length()==EDGES)
        val pre=IntArray(EDGES);val post=IntArray(EDGES);val weights=DoubleArray(EDGES);val incoming=DoubleArray(NODES)
        repeat(EDGES) {i->val edge=edges.getJSONArray(i);pre[i]=edge.getInt(0);post[i]=edge.getInt(1);weights[i]=edge.getDouble(2)
            require(pre[i] in 0 until NODES && post[i] in 0 until NODES && weights[i].isFinite() && weights[i]>0)
            incoming[post[i]]+=weights[i]}
        repeat(EDGES) {i->weights[i]=0.6*weights[i]/incoming[post[i]].coerceAtLeast(1.0)}
        Graph(pre,post,weights)
    }
    /** 5 bounded inputs -> fixed real-graph reservoir -> 22 readout features. Reset per candidate. */
    fun encode(input:DoubleArray):DoubleArray {
        require(input.size==5 && input.all {it.isFinite() && it in 0.0..1.0})
        val g=graph
        val drive=DoubleArray(NODES) {i->input.indices.sumOf {j->input[j]*(((i*17+j*31)%17)-8)/8.0}}
        var state=DoubleArray(NODES) {tanh(drive[it])}
        repeat(3) {
            val propagation=DoubleArray(NODES)
            repeat(EDGES) {i->propagation[g.post[i]]+=state[g.pre[i]]*g.weight[i]}
            state=DoubleArray(NODES) {tanh(drive[it]+propagation[it])}
        }
        val out=DoubleArray(22);out[0]=1.0
        input.copyInto(out,1)
        val counts=IntArray(16)
        repeat(NODES) {i->val group=i%16;out[6+group]+=state[i];counts[group]++}
        repeat(16) {out[6+it]/=counts[it].coerceAtLeast(1)}
        return out
    }
    // Offline synthetic scenario fit only. Not evidence of phone/network efficacy.
    val initialWeights:DoubleArray get()=doubleArrayOf(-0.3761048051970751,-0.3761048051970751,-0.9130677369434123,-0.6992947896384515,1.1725747914218507,0.051774400737369816,-0.13548072773861056,-0.1354807277386107,-0.13548072773861058,-0.1354807277386106,-0.13548072773861067,-0.13548072773861058,-0.13548072773861064,-0.1354807277386106,-0.13548072773861064,-0.13548072773861064,-0.1354807277386107,-0.1354807277386106,-0.13548072773861058,-0.1354807277386107,-0.13548072773861053,-0.1354807277386105)
}
